using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts non-deterministic
        // values like DateTime.UtcNow. Use a fixed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "ShopDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change #1: EF Core 9 Cosmos provider now uses "$type" as the
        // default discriminator property name instead of "Discriminator".
        // For existing documents that already store "Discriminator", you must
        // explicitly configure the old property name to avoid read failures.
        modelBuilder.Entity<Product>()
            .HasDiscriminator<string>("Discriminator")
            .HasValue<Product>("Product")
            .HasValue<DiscountedProduct>("DiscountedProduct");

        modelBuilder.Entity<Product>().ToContainer("Products");
        modelBuilder.Entity<Product>().HasPartitionKey(p => p.Category);
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public string Category { get; set; } = null!;
}

class DiscountedProduct : Product
{
    public decimal Discount { get; set; }
}

// Breaking change #2: EF Core 9 Cosmos provider removed synchronous I/O support.
// All queries/saves must use async methods (ToListAsync, SaveChangesAsync, etc.).
class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // WRONG (no longer compiles/runs in EF Core 9):
    // var items = _db.Products.ToList();

    // CORRECT — use async:
    public async Task<List<Product>> GetProductsAsync()
    {
        return await _db.Products.ToListAsync();
    }

    public async Task SaveProductAsync(Product product)
    {
        _db.Products.Add(product);
        await _db.SaveChangesAsync();
    }
}

